import{_ as n,a as l}from"./chunks/sensor_compass_calibrate_px4.DpiebXNN.js";import{_ as s,C as c,o as h,c as d,al as t,E as i,j as o,a as r}from"./chunks/framework.7vp1BMOE.js";const k=JSON.parse('{"title":"罗盘校准","description":"","frontmatter":{},"headers":[],"relativePath":"zh/config/compass.md","filePath":"zh/config/compass.md"}'),m={name:"zh/config/compass.md"};function p(u,e,f,g,b,v){const a=c("Badge");return h(),d("div",null,[e[2]||(e[2]=t('<h1 id="罗盘校准" tabindex="-1">罗盘校准 <a class="header-anchor" href="#罗盘校准" aria-label="Permalink to &quot;罗盘校准&quot;">​</a></h1><p>This process calibrates and configures all <a href="./../gps_compass/">magnetometers</a>. <em>QGroundControl</em> will guide you to position the vehicle in a number of set orientations and rotate the vehicle about the specified axis.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>It also auto-detects the compass orientation for external magnetometers (<a href="./../advanced_config/parameter_reference#SENS_MAG_AUTOROT">by default</a>). If you have <a href="./../assembly/mount_gps_compass#compass-orientation">mounted the compass</a> at a non-standard angle you will need to <a href="./../config/flight_controller_orientation#setting-the-compass-orientation">manually set the compass orientation</a> before calibrating.</p></div><h2 id="综述" tabindex="-1">综述 <a class="header-anchor" href="#综述" aria-label="Permalink to &quot;综述&quot;">​</a></h2><p>You will need to calibrate your compass(es) when you first setup your vehicle, and you may need to <a href="#recalibration">recalibrate</a> it if the vehicles is ever exposed to a very strong magnetic field, or if it is used in an area with abnormal magnetic characteristics.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Indications of a poor compass calibration include multicopter circling during hover, toilet bowling (circling at increasing radius/spiraling-out, usually constant altitude, leading to fly-way), or veering off-path when attempting to fly straight. <em>QGroundControl</em> should also notify the error <code>mag sensors inconsistent</code>.</p></div><p>The process calibrates all compasses and autodetects the orientation of any external compasses. If any external magnetometers are available, it then disables the internal magnetometers (these are primarily needed for automatic rotation detection of external magnetometers).</p><h3 id="types-of-calibration" tabindex="-1">Types of Calibration <a class="header-anchor" href="#types-of-calibration" aria-label="Permalink to &quot;Types of Calibration&quot;">​</a></h3><p>Several types of compass calibration are available:</p><ol><li><a href="#complete-calibration">Complete</a>: This calibration is required after installing the autopilot on an airframe for the first time or when the configuration of the vehicle has changed significantly. It compensates for hard and soft iron effects by estimating an offset and a scale factor for each axis.</li><li><a href="#partial-quick-calibration">Partial</a>: This calibration can be performed as a routine when preparing the vehicle for a flight, after changing the payload, or simply when the compass rose seems inaccurate. This type of calibration only estimates the offsets to compensate for a hard-iron effect.</li><li><a href="#large-vehicle-calibration">Large vehicle</a>: This calibration can be performed when the vehicle is too large or heavy to perform a complete calibration. This type of calibration only estimates the offsets to compensate for a hard-iron effect.</li></ol><h2 id="执行校准" tabindex="-1">执行校准 <a class="header-anchor" href="#执行校准" aria-label="Permalink to &quot;执行校准&quot;">​</a></h2><h3 id="操作前提" tabindex="-1">操作前提 <a class="header-anchor" href="#操作前提" aria-label="Permalink to &quot;操作前提&quot;">​</a></h3><p>Before starting the calibration:</p><ol><li>Choose a location away from large metal objects or magnetic fields.<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Metal is not always obvious! Avoid calibrating on top of an office table (often contain metal bars) or next to a vehicle. Calibration can even be affected if you&#39;re standing on a slab of concrete with uneven distribution of re-bar.</p></div></li></ol><p>::: 2. Connect via telemetry radio rather than USB if at all possible. USB can potentially cause significant magnetic interference. 3. If using an external compass (or a combined GPS/compass module), make sure it is <a href="./../assembly/mount_gps_compass">mounted</a> as far as possible from other electronics in order to reduce magnetic interference, and in a <em>supported orientation</em>.</p><h3 id="complete-calibration" tabindex="-1">Complete Calibration <a class="header-anchor" href="#complete-calibration" aria-label="Permalink to &quot;Complete Calibration&quot;">​</a></h3><p>The calibration steps are:</p><ol><li><p>Start <em>QGroundControl</em> and connect the vehicle.</p></li><li><p>Select <strong>&quot;Q&quot; icon &gt; Vehicle Setup &gt; Sensors</strong> (sidebar) to open <em>Sensor Setup</em>.</p></li><li><p>Click the <strong>Compass</strong> sensor button.</p><p><img src="'+n+'" alt="Select Compass calibration PX4"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>You should already have set the <a href="./../config/flight_controller_orientation">Autopilot Orientation</a>. If not, you can also set it here.</p></div></li></ol><p>:::</p><ol start="4"><li><p>Click <strong>OK</strong> to start the calibration.</p></li><li><p>把你的飞机放置在下面显示的某一个方向，并保持静止。 随后提示（方向图像变为黄色）在指定方向旋转飞行器。 该位置标定完成后，屏幕上的相应图示将变成绿色。</p><p><img src="'+l+'" alt="Compass calibration steps on PX4"></p></li><li><p>在机体的所有方向上重复校准步骤。</p></li></ol><p>Once you&#39;ve calibrated the vehicle in all the positions <em>QGroundControl</em> will display <em>Calibration complete</em> (all orientation images will be displayed in green and the progress bar will fill completely). You can then proceed to the next sensor.</p><h3 id="partial-quick-calibration" tabindex="-1">Partial &quot;Quick&quot; Calibration <a class="header-anchor" href="#partial-quick-calibration" aria-label="Permalink to &quot;Partial &quot;Quick&quot; Calibration&quot;">​</a></h3><p>This calibration is similar to the well-known figure-8 compass calibration done on a smartphone:</p><ol><li>Hold the vehicle in front of you and randomly perform partial rotations on all its axes. 2-3 oscillations of ~30 degrees in every direction is usually sufficient.</li><li>Wait for the heading estimate to stabilize and verify that the compass rose is pointing to the correct direction (this can take a couple of seconds).</li></ol><p>Notes:</p><ul><li>There is no start/stop for this type of calibration (the algorithm runs continuously when the vehicle is disarmed).</li><li>The calibration is immediately applied to the data (no reboot is required) but is saved to the calibration parameters after disarming the vehicle only (the calibration is lost if no arming/disarming sequence is performed between calibration and shutdown).</li><li>The amplitude and the speed of the partial rotations done in step 1 can affect the calibration quality. Following the advice above is usually enough.</li></ul><h3 id="large-vehicle-calibration" tabindex="-1">Large Vehicle Calibration <a class="header-anchor" href="#large-vehicle-calibration" aria-label="Permalink to &quot;Large Vehicle Calibration&quot;">​</a></h3>',27)),i(a,{type:"tip",text:"PX4 v1.15"}),e[3]||(e[3]=o("p",null,"This calibration process leverages external knowledge of the vehicle's orientation and location, along with a World Magnetic Model (WMM), to calibrate hard-iron biases. It is designed for large or heavy vehicles where full-axis rotation is impractical.",-1)),o("p",null,[e[0]||(e[0]=r("The calibration accepts an optional heading argument (",-1)),i(a,{type:"tip",text:"PX4 v1.18"}),e[1]||(e[1]=r("), allowing you to specify the vehicle's current true heading. This means you can perform a valid magnetometer calibration while the vehicle is pointed in any direction, not just North.",-1))]),e[4]||(e[4]=t('<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The <a href="#complete-calibration">complete calibration</a> is more reliable, and should be used if you can physically rotate the vehicle through all required orientations.</p><p>If the large vehicle calibration fails (magnetometer readings are inconsistent, or if yaw is unstable or incorrect) you will need to <a href="#recalibration">recalibrate</a> using the complete calibration.</p></div><details class="details custom-block"><summary>Details</summary><p>Implementation details</p><p>This implementation replaces an earlier version (PX4 v1.15 - PX4 v1.17) that required the vehicle to be facing True North.</p><p>The calibration process:</p><ul><li>Computes hard-iron bias offsets by comparing the expected Earth magnetic field vector (based on location and heading from WMM) with the measured field from the magnetometer(s).</li><li>Adjusts magnetometer offset parameters so the heading estimate aligns correctly without requiring full 3-axis rotation.</li><li>The calibration is applied immediately. Offsets persist once parameters are saved (typically on disarm or reboot).</li></ul></details><h4 id="操作前提-1" tabindex="-1">操作前提 <a class="header-anchor" href="#操作前提-1" aria-label="Permalink to &quot;操作前提&quot;">​</a></h4><ul><li>Obtain a valid GNSS fix (required for World Magnetic Model lookup).</li><li>Choose a location away from large metal objects or magnetic fields.</li><li>If using an external compass, ensure it is <a href="./../assembly/mount_gps_compass">mounted</a> as far as possible from other electronics.</li></ul><h4 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to &quot;Procedure&quot;">​</a></h4><ol><li><p><strong>Ensure GNSS Fix.</strong> This is required to look up the expected Earth magnetic field from WMM tables.</p></li><li><p><strong>Align the vehicle to a known heading.</strong> This can be True North (0°), or any other known heading relative to True North.</p></li><li><p>Open the <a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/analyze_view/mavlink_console.html" target="_blank" rel="noreferrer">QGroundControl MAVLink Console</a> and run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">commander</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> calibrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quick</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [heading]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Parameter</th><th>描述</th></tr></thead><tbody><tr><td><code>heading</code> (optional)</td><td>True heading of the vehicle in degrees (0–359). Defaults to 0° (North) if omitted.</td></tr></tbody></table><p><strong>Examples:</strong></p><table tabindex="0"><thead><tr><th>Vehicle Facing</th><th>通信</th></tr></thead><tbody><tr><td>North (0°)</td><td><code>commander calibrate mag quick</code></td></tr><tr><td>East (90°)</td><td><code>commander calibrate mag quick 90</code></td></tr><tr><td>South (180°)</td><td><code>commander calibrate mag quick 180</code></td></tr><tr><td>Southwest (225°)</td><td><code>commander calibrate mag quick 225</code></td></tr></tbody></table></li></ol><div class="info custom-block"><p class="custom-block-title">备注</p><ul><li>The vehicle doesn&#39;t need to be exactly level. Tilt is automatically compensated using the attitude estimate.</li><li>This calibration can also be triggered using the MAVLink command <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_FIXED_MAG_CAL_YAW" target="_blank" rel="noreferrer">MAV_CMD_FIXED_MAG_CAL_YAW</a>.</li></ul></div><h4 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h4><p>After calibration:</p><ol><li>Check that the heading indicator in QGroundControl is stable.</li><li>Rotate the vehicle to cardinal directions (N/E/S/W) and verify the compass heading matches.</li><li>If using multiple magnetometers, confirm the correct sensor priority is set.</li></ol><h2 id="recalibration" tabindex="-1">Recalibration <a class="header-anchor" href="#recalibration" aria-label="Permalink to &quot;Recalibration&quot;">​</a></h2><p>Recalibration is recommended whenever the magnetic environment of the vehicle has changed or when heading behavior appears unreliable.</p><p>You can use either complete calibration or mag quick calibration depending on the size of the vehicle and your ability to rotate it through the required orientations. Complete calibration provides the most accurate soft-iron compensation.</p><p>Recalibrate the compass when:</p><ul><li><em>The compass module or its mounting orientation has changed.</em> This includes replacing the GPS or mag unit, rotating the mast, or altering how the module is fixed to the airframe.</li><li><em>The vehicle has been exposed to a strong magnetic disturbance.</em> Examples include transport or storage near large steel structures, welding operations near the airframe, or operation close to high-current equipment.</li><li><em>Structural, wiring, or payload changes may have altered the magnetic field around the sensors.</em> New payloads, rerouted wires, additional batteries, or metal fasteners can introduce soft-iron effects that affect heading accuracy.</li><li><em>The vehicle is operated in a region with significantly different magnetic characteristics.</em> Large changes in latitude, longitude, or magnetic inclination can require re-estimation of offsets.</li><li><em>QGroundControl reports magnetometer inconsistencies</em>. For example, if you see the error <code>mag sensors inconsistent</code>.</li><li><em>Heading behavior does not match the vehicle’s observed orientation.</em> Symptoms include drifting yaw, sudden heading jumps when attempting to fly straight, and toilet bowling</li><li><em>QGroundControl</em> sends the error <code>mag sensors inconsistent</code>. This indicates that multiple magnetometers are reporting different headings.</li></ul><h2 id="additional-calibration-configuration" tabindex="-1">Additional Calibration/Configuration <a class="header-anchor" href="#additional-calibration-configuration" aria-label="Permalink to &quot;Additional Calibration/Configuration&quot;">​</a></h2><p>The processes above will autodetect, <a href="./../advanced_config/parameter_reference#SENS_MAG_AUTOROT">set default rotations</a>, calibrate, and prioritise, all available magnetometers. If external magnetometers are available, internal magnetometers are disabled.</p><p>Further compass configuration should generally not be required.</p><h3 id="enable-disable-a-compass" tabindex="-1">Enable/Disable a Compass <a class="header-anchor" href="#enable-disable-a-compass" aria-label="Permalink to &quot;Enable/Disable a Compass&quot;">​</a></h3><p>While no further configuration should be <em>required</em>, developers who wish to disable/enable compasses for any reason, such as testing, can do so using the compass parameters. These are prefixed with <a href="./../advanced_config/parameter_reference#CAL_MAG0_ID">CAL<em>MAGx</em></a> (where <code>x=0-3</code>):</p><ul><li><a href="./../advanced_config/parameter_reference#CAL_MAG0_ROT">CAL_MAGn_ROT</a> can be used to determine which compasses are internal. A compass is internal if <code>CAL_MAGn_ROT==1</code>.</li><li><a href="./../advanced_config/parameter_reference#CAL_MAG0_PRIO">CAL_MAGx_PRIO</a> sets the relative compass priority and can be used to disable a compass.</li></ul><h2 id="调试" tabindex="-1">调试 <a class="header-anchor" href="#调试" aria-label="Permalink to &quot;调试&quot;">​</a></h2><p>Raw comparison data for magnetometers (in fact, for all sensors) can be logged by setting <a href="./../advanced_config/parameter_reference#SDLOG_MODE">SDLOG_MODE=1</a> and <a href="./../advanced_config/parameter_reference#SDLOG_PROFILE">SDLOG_PROFILE=64</a>. See <a href="./../dev_log/logging">Logging</a> for more information.</p><h2 id="更多信息" tabindex="-1">更多信息 <a class="header-anchor" href="#更多信息" aria-label="Permalink to &quot;更多信息&quot;">​</a></h2><ul><li><a href="./../gps_compass/">Peripherals &gt; GPS &amp; Compass</a></li><li><a href="./../assembly/">Basic Assembly</a> (setup guides for each flight controller)</li><li><a href="./../advanced_config/compass_power_compensation">Compass Power Compensation</a> (Advanced Configuration)</li><li><a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/setup_view/sensors_px4.html#compass" target="_blank" rel="noreferrer">QGroundControl User Guide &gt; Sensors</a></li><li><a href="https://youtu.be/91VGmdSlbo4?t=2m38s" target="_blank" rel="noreferrer">PX4 Setup Video - @2m38s</a> (Youtube)</li></ul>',25))])}const C=s(m,[["render",p]]);export{k as __pageData,C as default};
